SELECT (SELECT pg_catalog.pg_class.relname) FROM pg_catalog.pg_class WHERE oid=1259;
SELECT unnest('1 2 3'::int2vector),generate_subscripts('1 2 3'::int2vector,1);
SELECT * FROM unnest('1 2'::int2vector,'42'::oidvector) WITH ORDINALITY;
SELECT * FROM generate_subscripts('42 99'::oidvector,1,true);
SELECT unnest(''::int2vector);
SELECT * FROM unnest(NULL::oidvector);
SELECT generate_subscripts(''::int2vector,1);
SELECT * FROM generate_subscripts('1 2'::int2vector,2);
SELECT 'foo' LIKE ANY(ARRAY['f%','b%']), 'foo' LIKE ALL(ARRAY['f%','%o']), 'FOO' ILIKE ANY(ARRAY['f%']), 'foo' NOT LIKE ANY(ARRAY['f%','b%']), 'foo' NOT LIKE ALL(ARRAY['x%','y%']), 'foo' LIKE ANY('{f%,b%}'), 'r'::"char"=ANY(ARRAY['r','p']);
CREATE SCHEMA client_hidden;
CREATE TABLE client_hidden.orders(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY);
CREATE INDEX orders_extra ON client_hidden.orders(id);
CREATE VIEW client_hidden.report AS SELECT id FROM client_hidden.orders;
CREATE TYPE client_hidden.order_value AS (id integer);
CREATE TABLE client_hidden."Mixed Name"(id integer);
SELECT 'client_hidden.orders'::regclass::text, 'client_hidden.orders_id_seq'::regclass::text, 'client_hidden.orders_pkey'::regclass::text, 'client_hidden.orders_extra'::regclass::text, 'client_hidden.report'::regclass::text, 'client_hidden.order_value'::regclass::text, 'client_hidden."Mixed Name"'::regclass::text;
SELECT pg_get_serial_sequence(a.attrelid::regclass::text,a.attname) FROM pg_attribute AS a WHERE a.attrelid='client_hidden.orders'::regclass AND a.attname='id';
SET search_path=client_hidden,public;
SELECT 'client_hidden.orders'::regclass::text, 'client_hidden.orders_extra'::regclass::text, 'client_hidden."Mixed Name"'::regclass::text;
CREATE TABLE public.orders(id integer);
SET search_path=public,client_hidden;
SELECT 'client_hidden.orders'::regclass::text,'public.orders'::regclass::text;
RESET search_path;
CREATE DOMAIN client_hidden.box_value AS box;
CREATE DOMAIN client_hidden.box_copy AS client_hidden.box_value;
SELECT typname,typdelim FROM pg_type WHERE oid IN ('box'::regtype,'box[]'::regtype,'integer'::regtype,'int2vector'::regtype,'client_hidden.box_value'::regtype,'client_hidden.box_value[]'::regtype,'client_hidden.box_copy'::regtype,'client_hidden.box_copy[]'::regtype) ORDER BY typname;
SELECT typname,oid,typarray,typdelim FROM pg_type WHERE oid=to_regtype('absent_client_extension');
DROP TABLE public.orders;
DROP SCHEMA client_hidden CASCADE;
